#!/usr/bin/env node
// client-drive.mjs — drive a desktop AI client (ChatGPT, Claude) on the Mini, for listing/test-cases.md's walks and videos.
// A node CLI rather than a set of shell scripts: the clients' facts are data (clients.json), walk.mjs calls the same verbs
// in-process, and every bash snippet is generated by one quoting helper that the selftest checks with `bash -n`.
//
// A verb that needs the screen (keys, clicks, capture) needs Terminal's Screen Recording + Accessibility grants: run from any
// other shell it re-runs ITSELF inside Terminal through run-in-terminal.sh (CLIENT_DRIVE_INSIDE=1 there) and prints what it
// printed. State (takes, snapshots, the mouse binary, the app half's profile, config backups) lives in engine/.runs/client-drive/.
//
//   place <client> full|left            new-chat <client>              say <client> <text file>     sidebar <client>
//   snap <png> [window|full] [client]   wait <client>                  set-model <client>           menus <client> <menu>
//   rec-start <take> window|full [client]   rec-stop <take>            mark <take> <label>          restart <client> [full|left]
//   app-start [right|full] [url]        app goto <path>|reload|shot <png>                           use <client> <role>
// <client>: chatgpt | claude (the Claude app; claude-app also reads) | claude-code (use only). Exit 0 ok, 1 failed, 2 usage.
import { readFileSync, writeFileSync, existsSync, mkdirSync, chmodSync, copyFileSync, appendFileSync, realpathSync, rmSync } from "node:fs";
import { spawnSync, spawn, execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { dirname, join, resolve } from "node:path";
import { homedir } from "node:os";
import { fileURLToPath } from "node:url";

export const HERE = dirname(fileURLToPath(import.meta.url));
export const ENGINE = dirname(dirname(HERE));                 // engine/tools/client-drive -> engine
export const REPO = dirname(ENGINE);
export const STATE = join(ENGINE, ".runs", "client-drive");
export const CLIENTS = JSON.parse(readFileSync(join(HERE, "clients.json"), "utf8"));
export const ROLES = ["admin", "member", "partner"];
export const MCP_URL = "https://agent.sharingu.xyz/mcp";
export const APP_URL = "https://agent.sharingu.xyz/sharingu-review";
export const CODEX_CONFIG = join(homedir(), ".codex", "config.toml");
const MOUSE = join(STATE, "bin", "mouse");
const CDP_PORT = 9333;
// Playwright's Chrome for Testing — never the owner's /Applications/Google Chrome.app
const CFT = join(homedir(), "Library/Caches/ms-playwright/chromium-1228/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing");
const APP_FRAMES = { right: [960, 25, 960, 1055], full: [0, 25, 1920, 1055] };

export const inside = () => process.env.CLIENT_DRIVE_INSIDE === "1";
export const sq = (s) => `'${String(s).replace(/'/g, `'\\''`)}'`;            // one shell word, whatever it holds
const osa = (...lines) => `osascript ${lines.map((l) => `-e ${sq(l)}`).join(" ")}`;
const sys = (app, what) => osa(`tell application "System Events" to tell process "${app}" to ${what}`);
const menuClick = (app, [menu, item]) => sys(app, `click menu item "${item}" of menu "${menu}" of menu bar 1`);
const activate = (app) => `${osa(`tell application "${app}" to activate`)}; sleep 0.3`;
const rectOf = (app) => `r=$(${sys(app, "get {position, size} of front window")} | tr -d ' ')`;   // r="x,y,w,h"

export const clientOf = (name) => {
  const key = name === "claude-app" ? "claude" : name;
  if (!CLIENTS[key] || key === "_") throw usage(`unknown client "${name}" (chatgpt, claude)`);
  return { key, ...CLIENTS[key] };
};
const usage = (m) => Object.assign(new Error(m), { usage: true });
const takeDir = (take) => { if (!/^[\w.-]+$/.test(String(take || ""))) throw usage("a take is letters, digits, . - _"); return join(STATE, "takes", take); };
const ensureState = () => { mkdirSync(STATE, { recursive: true }); chmodSync(STATE, 0o700); };

// scriptOf(verb, args) -> the bash text that does a screen verb, run as is inside Terminal (pure: the selftest bash -n's it)
export function scriptOf(verb, args) {
  const c = () => clientOf(args[0]);
  const frameOf = (p, f) => { const r = p.frames[f]; if (!r) throw usage(`frame: ${Object.keys(p.frames).join("|")}`); return r; };
  const place = (p, f) => { const [x, y, w, h] = frameOf(p, f); return [activate(p.app),
    sys(p.app, `set position of front window to {${x}, ${y}}`), sys(p.app, `set size of front window to {${w}, ${h}}`), "sleep 0.5"]; };
  const newChat = (p) => [activate(p.app), ...(p.menus.mode ? [menuClick(p.app, p.menus.mode), "sleep 1"] : []), menuClick(p.app, p.menus.newChat), "sleep 1.5"];
  const lines = (() => {
    switch (verb) {
      case "place": return place(c(), args[1] || "full");
      case "new-chat": return newChat(c());
      case "sidebar": { const p = c(); return [activate(p.app), menuClick(p.app, p.menus.sidebar)]; }
      case "menus": { const p = c(); if (!args[1]) throw usage("menus <client> <menu>");
        return [sys(p.app, `get name of every menu item of menu "${args[1]}" of menu bar 1`)]; }
      case "say": { const p = c(), file = args[1]; if (!file) throw usage("say <client> <text file>");
        // click the composer first where the window sits in a frame whose composer point is known
        const clicks = Object.entries(p.points || {}).filter(([, pt]) => pt.composer).map(([f, pt]) =>
          `[ "$r" = ${sq(frameOf(p, f).join(","))} ] && ${sq(MOUSE)} click ${pt.composer.join(" ")} && sleep 0.3`);
        return [activate(p.app), ...(clicks.length ? [rectOf(p.app), ...clicks.map((l) => `${l} || true`)] : []),
          `pbcopy < ${sq(resolve(file))}`, osa(`tell application "System Events" to keystroke "v" using command down`), "sleep 0.8",
          osa(`tell application "System Events" to key code 36`)]; }
      case "set-model": { const p = c(), pt = (p.points || {}).full;
        if (!pt || !pt.setModel) throw usage(`${p.key} has no model-picker points`);
        return [...place(p, "full"), ...pt.setModel.flatMap(([x, y]) => [`${sq(MOUSE)} click ${x} ${y}`, "sleep 1.2"]),
          osa(`tell application "System Events" to key code 53`), "sleep 0.5"]; }
      case "snap": { const [png, mode = "window", client = "chatgpt"] = args; if (!png) throw usage("snap <png> [window|full] [client]");
        if (mode === "full") return [`screencapture -x ${sq(resolve(png))}`];
        if (mode !== "window") throw usage("snap mode: window|full");
        return [rectOf(clientOf(client).app), `screencapture -x -R"$r" ${sq(resolve(png))}`, `echo "window $r"`]; }
      case "rec-start": { const [take, mode = "window", client = "chatgpt"] = args, d = takeDir(take);
        const crop = mode === "full" ? "" : mode === "window"
          ? [rectOf(clientOf(client).app), `IFS=, read -r x y w h <<< "$r"`, `crop="crop=$((w/2*2)):$((h/2*2)):$x:$y,"`] : null;
        if (crop === null) throw usage("rec-start mode: window|full");
        return [`mkdir -p ${sq(d)}`, ...(crop || [`crop=`]),
          `nohup ffmpeg -hide_banner -loglevel error -y -f avfoundation -capture_cursor 1 -framerate 25 -i "0:none" -vf "\${crop}fps=25" -c:v libx264 -preset veryfast -crf 18 -g 25 -pix_fmt yuv420p ${sq(join(d, "rec.mp4"))} > ${sq(join(d, "ffmpeg.log"))} 2>&1 < /dev/null &`,
          `echo $! > ${sq(join(d, "rec.pid"))}`, `date +%s.%N > ${sq(join(d, "rec.t0"))}`, `echo "recording ${take} (pid $(cat ${sq(join(d, "rec.pid"))}))"`]; }
      case "restart": { const p = c(); return [osa(`tell application "${p.app}" to quit`), "sleep 4", `open -a ${sq(p.path)}`, "sleep 8",
        osa(`tell application "${p.app}" to reopen`), ...place(p, args[1] || "full"), ...newChat(p)]; }
      default: throw usage(`not a screen verb: ${verb}`);
    }
  })();
  return ["#!/bin/bash", `# client-drive ${verb} — generated by client-drive.mjs`, "set -euo pipefail", ...lines, ""].join("\n");
}

// terminalScript(argv) -> the script run-in-terminal.sh runs to do this same command inside Terminal (each word sq-quoted)
export function terminalScript(argv, { node = process.execPath, file = fileURLToPath(import.meta.url), env = "CLIENT_DRIVE_INSIDE=1" } = {}) {
  return ["#!/bin/bash", `cd ${sq(ENGINE)} || exit 1`, `${env} exec ${[node, file, ...argv].map(sq).join(" ")}`, ""].join("\n");
}

// inTerminal(argv, timeout) -> the exit code: writes the re-run script and hands it to run-in-terminal.sh
export function inTerminal(argv, timeout = 120, opts) {
  ensureState(); const dir = join(STATE, "scripts"); mkdirSync(dir, { recursive: true });
  const f = join(dir, `run-${process.pid}-${Date.now()}.sh`); writeFileSync(f, terminalScript(argv, opts), { mode: 0o700 });
  const code = spawnSync("bash", [join(HERE, "run-in-terminal.sh"), f, String(timeout)], { stdio: "inherit" }).status ?? 1;
  if (code !== 124) rmSync(f);                                                // a timed-out run keeps its script to read
  return code;
}

const bash = (text) => spawnSync("bash", ["-c", text], { stdio: "inherit" }).status ?? 1;
const buildMouse = () => execFileSync("bash", [join(HERE, "build.sh")], { stdio: "inherit" });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// windowRect(app) -> [x, y, w, h] of its front window; windowShot(...) -> sha1 of that window's capture, its foot (the composer
// and its caret) left out. Inside Terminal only.
export const windowRect = (app) => execFileSync("osascript", ["-e", `tell application "System Events" to tell process "${app}" to get {position, size} of front window`])
  .toString().replace(/\s/g, "").split(",").map(Number);
export function windowShot(app, quietBottom = 0, [x, y, w, h] = windowRect(app), png = join(STATE, "wait.png")) {
  execFileSync("screencapture", ["-x", `-R${x},${y},${w},${Math.max(40, h - quietBottom)}`, png]);
  return createHash("sha1").update(readFileSync(png)).digest("hex");
}

// waitStill(client, { baseline, still, max }) -> { ok, secs }: polls the window until it has changed from `baseline` (the
// shot before the ask; given up on after 10 s) and then held still for `still` seconds; max seconds in all. "Still" allows
// two images (a caret's blink); an answer streaming or a thinking shimmer makes more.
export async function waitStill(name, { baseline = null, still = 3, max = 90, every = 1000 } = {}) {
  const p = clientOf(name), rect = windowRect(p.app), t0 = Date.now(); let seen = [], moved = !baseline;
  for (;;) {
    const h = windowShot(p.app, p.quietBottom, rect), now = Date.now();
    if (!moved && (h !== baseline || now - t0 > 10_000)) { moved = true; seen = []; }
    seen = [...seen, { h, at: now }].filter((s) => now - s.at <= still * 1000 + every);
    if (moved && now - seen[0].at >= still * 1000 && new Set(seen.map((s) => s.h)).size <= 2) return { ok: true, secs: Math.round((now - t0) / 1000) };
    if (now - t0 >= max * 1000) return { ok: false, secs: max };
    await sleep(every);
  }
}

export function mark(take, label) {
  const d = takeDir(take), t0 = Number(readFileSync(join(d, "rec.t0"), "utf8"));
  const line = `${(Date.now() / 1000 - t0).toFixed(3)} ${label}`; appendFileSync(join(d, "marks"), line + "\n"); return line;
}

export async function recStop(take) {
  const d = takeDir(take), pid = Number(readFileSync(join(d, "rec.pid"), "utf8"));
  try { process.kill(pid, "SIGINT"); } catch { /* already gone */ }            // ffmpeg finalises the file on SIGINT
  for (let i = 0; i < 20; i++) { try { process.kill(pid, 0); } catch { break; } await sleep(500); }
  const f = join(d, "rec.mp4"); return existsSync(f) ? `stopped ${take}: ${readFileSync(f).length} bytes` : `stopped ${take}: no file`;
}

// codexWithRole(text, role) -> config.toml with sharingu-<role> enabled and the other sharingu-<role> connections disabled.
// Only a connection's own table ([mcp_servers.sharingu-<r>], never its .env sub-table) gets the one `enabled = …` line.
export function codexWithRole(text, role) {
  if (!ROLES.includes(role)) throw usage(`role: ${ROLES.join("|")}`);
  const head = /^\s*\[mcp_servers\."?(sharingu-([a-z]+))"?\]\s*$/, out = [], seen = new Set(); let cur = null;
  for (const line of String(text).split("\n")) {
    if (/^\s*\[/.test(line)) {
      const m = head.exec(line); cur = m && ROLES.includes(m[2]) ? m[1] : null; out.push(line);
      if (cur) { seen.add(cur); out.push(`enabled = ${cur === `sharingu-${role}`}`); }
      continue;
    }
    if (cur && /^\s*enabled\s*=/.test(line)) continue;
    out.push(line);
  }
  if (!seen.has(`sharingu-${role}`)) throw new Error(`no sharingu-${role} connection in the config: run connect.sh chatgpt ${role} first`);
  return out.join("\n");
}

// switchCodex(role, { config, backups }) -> the backup's path: the config backed up (600), then rewritten
export function switchCodex(role, { config = CODEX_CONFIG, backups = join(STATE, "backups") } = {}) {
  const text = readFileSync(config, "utf8"), next = codexWithRole(text, role);
  mkdirSync(backups, { recursive: true, mode: 0o700 });
  const b = join(backups, `config.toml.${new Date().toISOString().replace(/[:.]/g, "-")}`);
  copyFileSync(config, b); chmodSync(b, 0o600); writeFileSync(config, next); return b;
}

// the app half: Chrome for Testing on CDP 9333 in its own profile (700), beside the client
export function appStart(frame = "right", url = APP_URL) {
  if (!APP_FRAMES[frame]) throw usage("app-start [right|full] [url]");
  if (!existsSync(CFT)) throw new Error(`no Chrome for Testing at ${CFT}`);
  ensureState(); const prof = join(STATE, "app-profile"); mkdirSync(prof, { recursive: true }); chmodSync(prof, 0o700);
  const [x, y, w, h] = APP_FRAMES[frame];
  const child = spawn(CFT, [`--user-data-dir=${prof}`, `--remote-debugging-port=${CDP_PORT}`, "--no-first-run", "--no-default-browser-check",
    "--use-mock-keychain", "--password-store=basic", "--test-type", `--window-position=${x},${y}`, `--window-size=${w},${h}`, `--app=${url}`],
    { detached: true, stdio: "ignore" });
  child.unref(); return `app browser pid ${child.pid} on CDP ${CDP_PORT}`;
}

// cdp(fn) -> fn(send, events) on the app half's first page, over the DevTools websocket (no playwright needed)
async function cdp(fn) {
  const pages = await (await fetch(`http://127.0.0.1:${CDP_PORT}/json/list`)).json().catch(() => { throw new Error(`no app half on CDP ${CDP_PORT}: app-start first`); });
  const page = pages.find((p) => p.type === "page"); if (!page) throw new Error("the app half has no page");
  const ws = new WebSocket(page.webSocketDebuggerUrl); let id = 0; const waiting = new Map(), listeners = [];
  ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && waiting.has(m.id)) { waiting.get(m.id)(m); waiting.delete(m.id); } else listeners.forEach((l) => l(m)); };
  await new Promise((r, j) => { ws.onopen = r; ws.onerror = () => j(new Error("CDP refused")); });
  const send = (method, params = {}) => new Promise((r, j) => { const n = ++id; waiting.set(n, (m) => (m.error ? j(new Error(m.error.message)) : r(m.result))); ws.send(JSON.stringify({ id: n, method, params })); });
  const loaded = () => new Promise((r) => { const t = setTimeout(r, 20_000); listeners.push((m) => { if (m.method === "Page.loadEventFired") { clearTimeout(t); r(); } }); });
  try { await send("Page.enable"); return await fn(send, loaded); } finally { ws.close(); }
}

export async function app(cmd, arg) {
  return cdp(async (send, loaded) => {
    if (cmd === "goto") { if (!arg) throw usage("app goto <path>"); const l = loaded(); await send("Page.navigate", { url: /^https?:/.test(arg) ? arg : APP_URL + arg }); await l; await sleep(800); }
    else if (cmd === "reload") { const l = loaded(); await send("Page.reload"); await l; await sleep(800); }
    else if (cmd === "shot") { if (!arg) throw usage("app shot <png>"); writeFileSync(resolve(arg), Buffer.from((await send("Page.captureScreenshot", { format: "png" })).data, "base64")); }
    else throw usage("app goto <path>|reload|shot <png>");
    const { result } = await send("Runtime.evaluate", { expression: "location.pathname + ' · ' + document.title", returnByValue: true });
    return `${cmd} ${result.value}`;
  });
}

export const SCREEN_VERBS = new Set(["place", "new-chat", "say", "sidebar", "menus", "set-model", "snap", "rec-start", "restart", "wait"]);

// run(argv) -> exit code
export async function run(argv) {
  const [verb, ...args] = argv;
  if (verb === "snap" && args[0]) args[0] = resolve(args[0]);                 // a path is the caller's, not Terminal's cwd
  if (verb === "say" && args[1]) args[1] = resolve(args[1]);
  if (verb === "say" || verb === "set-model") buildMouse();                   // a no-op once built
  if (SCREEN_VERBS.has(verb) && !inside()) {
    if (verb === "wait") clientOf(args[0]); else scriptOf(verb, args);         // a usage error answers here, not in Terminal
    return inTerminal([verb, ...args], verb === "restart" ? 60 : verb === "wait" ? 150 : 45);
  }
  switch (verb) {
    case "wait": { const r = await waitStill(args[0]); console.log(r.ok ? `still after ${r.secs}s` : `still moving after ${r.secs}s`); return r.ok ? 0 : 1; }
    case "mark": if (!args[1]) throw usage("mark <take> <label>"); console.log(mark(args[0], args.slice(1).join(" "))); return 0;
    case "rec-stop": console.log(await recStop(args[0])); return 0;
    case "app-start": console.log(appStart(args[0], args[1])); return 0;
    case "app": console.log(await app(args[0], args[1])); return 0;
    case "use": {
      const [client, role] = args; if (!ROLES.includes(role)) throw usage(`use <client> <role: ${ROLES.join("|")}>`);
      if (client === "claude-code") { console.log(`claude-code: walk.mjs enables sharingu-${role} per run (--allowedTools); nothing to switch`); return 0; }
      const p = clientOf(client);
      if (p.connections !== "codex") { console.log(`${p.app}: its connectors live in the Claude account, switched by hand (the chat's connectors menu: only sharingu-${role} on)`); return 2; }
      console.log(`backed up ${switchCodex(role)}; sharingu-${role} enabled, the other roles disabled`);
      return run(["restart", client]);
    }
    default:
      if (SCREEN_VERBS.has(verb)) return bash(scriptOf(verb, args));
      throw usage(`verbs: ${[...SCREEN_VERBS, "mark", "rec-stop", "app-start", "app", "use"].join(" ")}`);
  }
}

const runDirectly = () => { try { return realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1] || ""); } catch { return false; } };
if (runDirectly()) {
  run(process.argv.slice(2)).then((code) => process.exit(code), (e) => { console.error(e.message); process.exit(e.usage ? 2 : 1); });
}
